Fonte fornecida: src/reservations.ts, linhas a partir de 1:
```ts
export async function reserve(db: Database, itemId: string) {
  const item = await db.one(
    'SELECT quantity FROM inventory WHERE id = $1', [itemId]
  );
  if (item.quantity < 1) return { reserved: false };
  await db.query(
    'UPDATE inventory SET quantity = quantity - 1 WHERE id = $1', [itemId]
  );
  return { reserved: true };
}
```

